    title: () => `Hrnečku, vař!`,
    text: (c) => {
      const { g, n } = c;
      return [
        { t: `Dnes večer se ${c.H} ${g('stane', 'stane', 'stanou')} ${g('hrdinou', 'hrdinkou', 'hrdiny', 'hrdinkami')} jedné moc dobré pohádky. Moc dobré – a moc sladké!` },
        { t: `Bylo nebylo, ${c.inTown} ${g('žil', 'žila', 'žili')} ${c.H}.` },
        { t: `Jednou ${g('šel', 'šla', 'šli')} do lesa na borůvky. Borůvek bylo málo, ale u pařezu seděla stařenka v šátku s puntíky a v klíně držela malý hliněný hrneček.` },
        { t: `„${n('Pomůžeš', 'Pomůžete')} mi vstát?“ poprosila stařenka. ${g('Podal', 'Podala', 'Podali')} jí ruku a stařenka se usmála od ucha k uchu.` },
        { t: `„Za to, že ${n('máš', 'máte')} hodné srdce, ${n('dostaneš', 'dostanete')} tenhle hrneček. Když mu ${n('řekneš', 'řeknete')}: Hrnečku, vař! – uvaří sladkou kaši. A když ${n('řekneš', 'řeknete')}: Hrnečku, dost! – přestane. Hlavně to druhé ${n('nezapomeň', 'nezapomeňte')}!“` },
        { t: `Hrneček byl úplně obyčejný. Hliněný, trochu oprýskaný a s modrým kvítkem na boku. Kdo by řekl, že je kouzelný?` },
        { t: `${c.H} ${g('běžel', 'běžela', 'běželi')} domů. Hrneček na stůl a pak to kouzelné slovo: „Hrnečku, vař!“ Hrneček zabublal a už byl plný sladké, voňavé kaše s máslem a skořicí.`, sfx: 'magic' },
        { t: `„Hrnečku, dost!“ A hrneček přestal. Kaše byla tak dobrá, že se po ní všichni olizovali až po lokty.` },
        { t: `Hrneček uměl uvařit i jiné dobroty. Když se ho hezky poprosilo, uvařil třeba i to nejlepší jídlo na světě: ${c.food}.` },
        { t: `Jednoho dne ${g('odešel', 'odešla', 'odešli')} ${c.H} na celé odpoledne ven.` },
        { t: `Hrneček zůstal na stole u okna. A kolem šel soused Bručoun. Pan Bručoun byl veliký mlsoun. Uviděl hrneček, rozhlédl se a zašeptal: „Hrnečku, vař!“ Hrneček zabublal a začal vařit.` },
        { t: `Pan Bručoun bydlel hned vedle a celé dny čichal, co kde voní. Když se u sousedů peklo, stál u plotu. Když se u sousedů vařilo, stál u okna. A dnes z okna voněla kaše.` },
        { t: `Bručoun jedl a jedl, až už nemohl. „Tak už stačí,“ řekl. Hrneček vařil dál. „Přestaň!“ Hrneček vařil dál. „Hrnečku, konec! Hrnečku, stop! Hrnečku, hotovo!“ Hrneček vařil a vařil a vařil.` },
        { t: `Kaše přetekla přes okraj, přes stůl, na podlahu. Vytekla dveřmi na dvorek, z dvorku na ulici a z ulice na náves. Blub, blub, blub!` },
        { t: `Kaše už byla po kolena, pak po pás. Psi v ní plavali jako v rybníce a děti si z ní stavěly hrady jako z písku. Jen pan Bručoun lomil rukama.` },
        { t: `Kaše tekla kolem obchodu, kolem školy i kolem hasičárny. Kočky utíkaly na stromy, slepice na plot a pan starosta až na střechu. Hasiči vyjeli s houkačkou, ale na kaši nebyli zvyklí.`, sfx: 'horn' },
        { t: c.near.length ? `Sladkou řeku bylo vidět až z okolí. ${listCz(c.near.slice(0, 2))} – tam všude si lidé ukazovali, co se to valí.` : `Sladkou řeku bylo vidět až z okolních vesnic. Všude si lidé ukazovali, co se to tam valí.` },
        { t: `A pak se ${c.H} ${g('vrátil', 'vrátila', 'vrátili')} domů.` },
        { t: `Na kraji návsi ${g('zůstal', 'zůstala', 'zůstali')} stát s ${n('otevřenou pusou', 'otevřenými pusami')}. Všude kaše! A uprostřed v neckách plaval pan Bručoun a volal: „Pomóóóc!“` },
        { t: `${c.H} se zhluboka ${g('nadechl', 'nadechla', 'nadechli')}.` },
        { t: `A pak ${g('zavolal', 'zavolala', 'zavolali')} tak nahlas, jak jen ${g('uměl', 'uměla', 'uměli')}: „Hrnečku, dost!“` },
        { t: `Hrneček udělal poslední blub – a přestal. Bylo ticho. Jen kaše pomaličku chladla na sluníčku.`, sfx: 'ding' },
        { t: `Pan Bručoun vylezl z necek celý ulepený. Na hlavě měl kaši jako čepici a na nose kousek skořice. „Děkuju,“ zamumlal. „To slovíčko jsem zapomněl.“` },
        { t: `Pak vyšla celá obec s lžícemi. Jedly děti, jedli dědečkové, jedli hasiči, kočky i slepice. Jedli až do večera, než byla náves čistá. A pan Bručoun se omluvil a slíbil, že už nikdy nebude brát, co mu nepatří.` },
        { t: `A hrneček? Ten stojí na poličce a vaří jen tomu, kdo si pamatuje obě kouzelná slova. ${n('A ty', 'A vy')} si je ${n('pamatuješ', 'pamatujete')}? Hrnečku, vař… a hrnečku…?`, pause: 4 },
        { t: `Dost! Výborně. Dobrou noc, ${c.h.voc}.` },
      ];
    },
